def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    names = sorted(packages)

    if any(name not in packages for name in roots):
        return {'error': 'unsatisfiable'}

    bounds = {name: (interval[0], interval[1])
              for name, interval in roots.items()}
    best_vector = None
    best_versions = None

    def search(assigned, required, constraints):
        nonlocal best_vector, best_versions

        pending = required - assigned.keys()
        if not pending:
            vector = tuple(assigned[name]['version'] if name in assigned else -1
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: assigned[name]['version']
                                 for name in sorted(assigned)}
            return

        if best_vector is not None:
            upper = []
            for name in names:
                if name in assigned:
                    upper.append(assigned[name]['version'])
                    continue
                low, high = constraints.get(name, (None, None))
                versions = [row['version'] for row in packages[name]
                            if (low is None or row['version'] >= low)
                            and (high is None or row['version'] <= high)
                            and row['version'] not in blocked.get(name, [])]
                upper.append(max([-1] + versions))
            if tuple(upper) <= best_vector:
                return

        name = min(pending)
        low, high = constraints.get(name, (None, None))
        candidates = [row for row in choose(packages.get(name, []))
                      if (low is None or row['version'] >= low)
                      and (high is None or row['version'] <= high)
                      and row['version'] not in blocked.get(name, [])]

        for row in candidates:
            next_constraints = dict(constraints)
            next_required = set(required)
            valid = True
            for dep in row.get('deps', []):
                dep_name = dep['name']
                dep_low = dep['min']
                dep_high = dep['max']
                if dep_name not in packages:
                    valid = False
                    break
                old_low, old_high = next_constraints.get(dep_name, (None, None))
                new_low = dep_low if old_low is None else max(old_low, dep_low)
                new_high = dep_high if old_high is None else min(old_high, dep_high)
                if new_low > new_high:
                    valid = False
                    break
                next_constraints[dep_name] = (new_low, new_high)
                next_required.add(dep_name)
                if (dep_name in assigned and
                        not new_low <= assigned[dep_name]['version'] <= new_high):
                    valid = False
                    break
            if not valid:
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = row
            search(next_assigned, next_required, next_constraints)

    search({}, set(roots), bounds)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
